"""The committed icon SVG is generated by tools/make_icons.py, not hand-edited.

``icon_svg()`` in the tool is the source of the design; ``tools/make_icons.py``
writes ``aiusageclockicon.svg`` (and renders the PNG, ICO and ICNS from it),
overwriting whatever is there. A hand edit of the SVG would be lost on the next
run, and an edit of ``icon_svg()`` without a re-run would leave the shipped
icon behind, so the two must stay identical.
"""

from __future__ import annotations

import importlib.util
from pathlib import Path

import pytest

from aiusageclock import identity

REPO_ROOT = Path(__file__).resolve().parents[1]
TOOL = REPO_ROOT / "tools" / "make_icons.py"
ICON_SVG = REPO_ROOT / "src" / "aiusageclock" / "assets" / f"{identity.ICON_BASENAME}.svg"


def generated_svg(monkeypatch) -> str:
    """What ``icon_svg()`` returns, without running the tool's ``main()``.

    The module imports PyQt6 and asks for the offscreen Qt platform at import
    time, so the variable is set through monkeypatch to leave the environment as
    found. It is loaded under a private name and not added to ``sys.modules``.
    """
    monkeypatch.setenv("QT_QPA_PLATFORM", "offscreen")
    spec = importlib.util.spec_from_file_location("make_icons_under_test", TOOL)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.icon_svg()


def first_difference(committed: str, generated: str) -> str | None:
    """The first line where the two SVGs differ, or None when they are identical."""
    if committed == generated:
        return None
    committed_lines = committed.split("\n")
    generated_lines = generated.split("\n")
    for number, (have, want) in enumerate(zip(committed_lines, generated_lines), start=1):
        if have != want:
            return f"line {number}: committed {have!r}, icon_svg() gives {want!r}"
    return (
        f"committed file has {len(committed_lines)} lines, "
        f"icon_svg() gives {len(generated_lines)}"
    )


def test_the_committed_svg_is_what_the_icon_tool_generates(monkeypatch):
    difference = first_difference(
        ICON_SVG.read_text(encoding="utf-8"), generated_svg(monkeypatch)
    )

    assert difference is None, (
        f"{ICON_SVG.name} differs from icon_svg() in tools/make_icons.py "
        f"({difference}). Edit icon_svg() and run the tool; do not edit the SVG by hand."
    )


def test_the_generator_is_deterministic(monkeypatch):
    assert generated_svg(monkeypatch) == generated_svg(monkeypatch)


def test_an_edit_inside_a_line_is_reported_at_that_line(monkeypatch):
    # Whatever the design is, put one character in front of its middle line.
    generated = generated_svg(monkeypatch)
    lines = generated.split("\n")
    assert len(lines) > 2, "the generated SVG should be more than a single line"
    middle = len(lines) // 2
    lines[middle] = "x" + lines[middle]

    difference = first_difference("\n".join(lines), generated)

    assert difference is not None and difference.startswith(f"line {middle + 1}:")
    # Counterpart: the unedited text has no difference.
    assert first_difference(generated, generated) is None


@pytest.mark.parametrize(
    ("edit", "expected"),
    [
        (lambda svg: svg.replace("</svg>", "<!-- hand edit --></svg>"), "line "),
        (lambda svg: svg.rstrip("\n"), "lines"),
    ],
    ids=["extra element", "missing final newline"],
)
def test_a_hand_edited_svg_is_noticed(monkeypatch, edit, expected):
    generated = generated_svg(monkeypatch)

    difference = first_difference(edit(generated), generated)

    assert difference is not None and expected in difference
    assert first_difference(generated, generated) is None
